    (hc₁ : NormalizedChannel μ₁ ν₁ r₁)
    (hc₂ : NormalizedChannel μ₂ ν₂ r₂) :
    overproductionGap (ProductStep R S) (a, b)
        (productMu μ₁ μ₂) (productNu ν₁ ν₂) (productConditional r₁ r₂) =
